WITH valid_shipments AS (SELECT *, DATEDIFF(CURRENT_DATE(), delivered_date) AS days_since_delivered_date FROM shipments WHERE status = 'IN_TRANSIT' OR cost BETWEEN 32 AND 84), CarrierSummary AS (SELECT carrier, COUNT(days_since_delivered_date) AS days_since_delivered_date_count, COUNT(DISTINCT cost) AS unique_orders FROM valid_shipments GROUP BY carrier) SELECT carrier, days_since_delivered_date_count, unique_orders FROM CarrierSummary WHERE unique_orders < 7 ORDER BY days_since_delivered_date_count DESC, carrier LIMIT 10;
